    86	        server.exception(HotelException.class, (exception, ctx) -> {
    87	            ctx.status(httpStatus(exception.errorCode()));
    88	            ctx.json(new ErrorResponse(exception.errorCode().name(), exception.getMessage()));
    89	        });
    90	    }
