    92	    private static int httpStatus(ErrorCode errorCode) {
    93	        return switch (errorCode) {
    94	            case INVALID_REQUEST -> 400;
    95	            case ROOM_NOT_FOUND, RESERVATION_NOT_FOUND -> 404;
    96	            case ROOM_UNAVAILABLE, OPERATION_NOT_ALLOWED -> 409;
    97	            case CAPACITY_EXCEEDED -> 422;
    98	        };
    99	    }
