   101	    private static NewReservation readNewReservation(Context ctx) {
   102	        CreateReservationRequest body;
   103	        try {
   104	            body = ctx.bodyAsClass(CreateReservationRequest.class);
   105	        } catch (Exception unreadableBody) { // Jackson's own exceptions are checked, but reach here unwrapped
   106	            throw new HotelException(ErrorCode.INVALID_REQUEST, "the body is not a valid reservation request");
   107	        }
   108	        if (body == null
   109	                || body.roomNumber() == null
   110	                || isBlank(body.guestName())
   111	                || isBlank(body.guestEmail())
   112	                || isBlank(body.guestCpf())
   113	                || body.checkIn() == null
   114	                || body.checkOut() == null
   115	                || body.guests() == null
   116	                || body.ratePlan() == null) {
   117	            throw new HotelException(ErrorCode.INVALID_REQUEST, "every field of the reservation is required");
   118	        }
   119	        Guest guest = new Guest(body.guestName(), body.guestEmail(), body.guestCpf());
   120	        return new NewReservation(
   121	                body.roomNumber(), guest, body.checkIn(), body.checkOut(), body.guests(), body.ratePlan());
   122	    }
