   125	        String id = ctx.pathParam("id");
   126	        try {
   127	            return Long.parseLong(id);
   128	        } catch (NumberFormatException notANumber) {
   129	            throw new HotelException(ErrorCode.RESERVATION_NOT_FOUND, "reservation " + id + " does not exist");
   130	        }
   131	    }
